              <span className="min-w-0 text-sm"><b>Rx · {r.patient}</b><br /><span className={muted}>{r.items}</span></span>
              {r.done ? <Pill tone="good">{t("dispensed")}</Pill> : <button className={btnPrimary} onClick={() => update((d) => ({ ...d, rx: d.rx.map((x) => x.id === r.id ? { ...x, done: true } : x) }), `Dispensed for ${r.patient}`, t("tDone"))}>{t("dispense")}</button>}
