function Tpa() {
  const { t, data, update, money, now, num } = useApp();
  const stages = ["preAuth", "approved", "finalSent", "settled"];
  const limitMin = (stage: number) => (stage === 0 ? 60 : stage === 2 ? 180 : 0);
  const fmt = (ms: number) => { const m = Math.floor(ms / MIN), s = Math.floor((ms % MIN) / 1000); return m >= 60 ? `${num(Math.floor(m / 60))}h ${num(m % 60)}m` : `${num(m)}m ${num(s)}s`; };
  return (
    <div className="grid gap-4">
      <p className={`text-sm ${muted}`}><Clock size={14} className="me-1 inline" aria-hidden="true" />{t("limitNote")}</p>
      <div className="-mx-4 overflow-x-auto px-4">
        <div className="grid min-w-[880px] grid-cols-4 gap-3">
          {stages.map((s, si) => (
            <div key={s} className="rounded-xl bg-[#ECEDF0] p-3 dark:bg-[#17171A]">
              <div className={`${label} mb-2 flex justify-between`}><span>{t(s)}</span><span>{num(data.claims.filter((c) => c.stage === si).length)}</span></div>
              <div className="grid gap-2">
                {data.claims.filter((c) => c.stage === si).map((c) => { const el = now - c.stageStart; const lim = limitMin(c.stage); const over = lim > 0 && el > lim * MIN; return (
                  <div key={c.id} className={`${panel} p-3 ${over ? "border-[#D93A3A] dark:border-[#F28A8A]" : ""}`}>
                    <div className="font-semibold">{c.patient}</div>
                    <div className={`text-xs ${muted}`}>{c.insurer} · <span className="tabular-nums">{money(c.amount)}</span></div>
                    {c.stage < 3 && <div className="mt-1 text-xs tabular-nums">{t("timeInStage")}: {fmt(el)}</div>}
                    {over && <div className="mt-1"><Pill tone="bad">{t("pastLimit")}</Pill></div>}
                    <div className={`${label} mt-2`}>{t("documents")}</div>
                    {c.docs.map((dc, di) => (
                      <label key={dc.name} className="flex min-h-[44px] items-center gap-2 text-sm"><input type="checkbox" className="h-6 w-6 accent-[#1F9D6B]" checked={dc.ok} onChange={() => update((d) => ({ ...d, claims: d.claims.map((x) => x.id === c.id ? { ...x, docs: x.docs.map((y, yi) => yi === di ? { ...y, ok: !y.ok } : y) } : x) }), `Claim ${c.patient}: ${dc.name} ${dc.ok ? "unchecked" : "checked"}`)} />{dc.name}</label>
                    ))}
                    {c.stage < 3 && <button className={`${btn} mt-2 w-full`} disabled={c.docs.some((d) => !d.ok)} onClick={() => update((d) => ({ ...d, claims: d.claims.map((x) => x.id === c.id ? { ...x, stage: x.stage + 1, stageStart: Date.now() } : x) }), `Claim ${c.patient} moved to ${stages[c.stage + 1]}`, t("tDone"))}>{t("moveNext")}</button>}
                  </div>); })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function Supply() {
  const { t, data, update, num, branch } = useApp();
  const rows = data.stock.filter((s) => branch === "all" || s.branch === branch);
  const suggestion = (s: StockT): { k: "transfer" | "returnDist" | "useFirst"; why: string } | null => {
    if (s.expiryDays > 90 || s.flag) return null;
    const monthsLeft = s.expiryDays / 30, canUse = s.monthlyUse * monthsLeft;
    if (canUse >= s.qty) return { k: "useFirst", why: `Uses ${num(Math.round(canUse))} before expiry` };
    const other = data.stock.find((o) => o.drug === s.drug && o.branch !== s.branch);
    if (other && other.monthlyUse * monthsLeft >= s.qty - canUse) return { k: "transfer", why: `${BRANCH_NAME[other.branch]} uses ${num(other.monthlyUse)}/month` };
    return { k: "returnDist", why: `${num(Math.round(s.qty - canUse))} units will expire unused` };
  };
  const apply = (s: StockT, k: "transfer" | "returnDist" | "useFirst") => {
    if (k === "useFirst") update((d) => ({ ...d, stock: d.stock.map((x) => x.id === s.id ? { ...x, flag: "useFirst" } : x) }), `${s.drug} ${s.batch}: use first`, t("tDone"));
    else if (k === "returnDist") update((d) => ({ ...d, stock: d.stock.map((x) => x.id === s.id ? { ...x, qty: Math.ceil(x.monthlyUse * (x.expiryDays / 30)), flag: "returned" } : x) }), `${s.drug} ${s.batch}: surplus returned to distributor`, t("tDone"));
    else { const moveQty = Math.floor(s.qty - s.monthlyUse * (s.expiryDays / 30)); update((d) => ({ ...d, stock: d.stock.map((x) => x.id === s.id ? { ...x, qty: x.qty - moveQty, flag: "transferred" } : x.drug === s.drug && x.branch !== s.branch ? { ...x, qty: x.qty + moveQty } : x) }), `${s.drug} ${s.batch}: ${moveQty} transferred`, t("tDone")); }
  };
  return (
    <Section title={t("stock")}>
      <div className="overflow-x-auto">
        <table className="w-full min-w-[640px] text-sm">
          <thead><tr className={label}><th className="py-2 text-start">{t("drug")}</th><th className="text-end">{t("qty")}</th><th className="text-end">{t("expiresIn")}</th><th className="ps-3 text-start">{t("nearExpiry")}</th></tr></thead>
          <tbody>
            {rows.map((s) => { const sug = suggestion(s); const low = s.qty < s.reorderLevel; return (
              <tr key={s.id} className={`border-t align-top ${hair}`}>
                <td className="py-2"><div className="font-semibold">{s.drug}</div><div className={`font-mono text-xs ${muted}`}>{s.batch} · {BRANCH_NAME[s.branch]}</div></td>
                <td className="py-2 text-end tabular-nums">{num(s.qty)}{low && <div><Pill tone="warn">{t("lowStock")}</Pill></div>}</td>
                <td className="py-2 text-end"><Pill tone={s.expiryDays <= 45 ? "bad" : s.expiryDays <= 90 ? "warn" : "good"}>{num(s.expiryDays)} {t("days")}</Pill></td>
                <td className="py-2 ps-3">
                  {sug && <div className="grid gap-1"><span className="text-xs"><b>{t(sug.k)}</b> — {sug.why}</span><button className={btnPrimary} onClick={() => apply(s, sug.k)}>{t(sug.k)}</button></div>}
                  {s.flag && <Pill tone="good">{t(s.flag === "useFirst" ? "useFirst" : s.flag === "returned" ? "returnDist" : "transfer")}</Pill>}
                  {low && <button className={`${btn} mt-1`} onClick={() => update((d) => ({ ...d, stock: d.stock.map((x) => x.id === s.id ? { ...x, qty: x.qty + x.reorderLevel * 2 } : x) }), `Reorder placed: ${s.drug} (${s.reorderLevel * 2})`, t("tDone"))}>{t("reorder")}</button>}
                </td>
              </tr>); })}
          </tbody>
        </table>
      </div>
    </Section>
  );
}

